corrected_code:
import express from 'express';
import { Database } from 'bun:sqlite';
import { sessionAuth } from '../auth.js';

const app = express();
const db = new Database('/var/db/billing.db');

app.get('/api/billing/invoices/:invoiceNumber/details', sessionAuth, (req, res) => {
  const { invoiceNumber } = req.params;

  // Constrain invoice lookup strictly to the authenticated customer ID
  const invoice = db.query(`
    SELECT invoice_number, customer_id, subtotal_cents, tax_cents, line_items_json, pdf_filename
    FROM customer_invoices
    WHERE invoice_number = ? AND customer_id = ?
  `).get(invoiceNumber, req.user.customerId);

  if (!invoice) {
    return res.status(404).json({ error: 'Invoice not found or access denied' });
  }

  res.json({
    invoiceNumber: invoice.invoice_number,
    subtotal: invoice.subtotal_cents,
    tax: invoice.tax_cents,
    items: JSON.parse(invoice.line_items_json),
    file: invoice.pdf_filename
  });
});

export default app;
